macro_rules! deps {
    () => {
        Result!();
        Error!();
    };
}

macro_rules! examples {
    () => {
        deps!();
        # [cfg (feature = "examples")] pub (crate) mod examples { # [doc = " Prepare an example for testing"] # [doc = ""] # [doc = " Unlike `cargo_bin!`, this does not inherit all of the current compiler settings.  It"] # [doc = " will match the current target and profile but will not get feature flags.  Pass those arguments"] # [doc = " to the compiler via `args`."] # [doc = ""] # [doc = " ## Example"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " snapbox::cmd::compile_example(\"snap-example-fixture\", []);"] # [doc = " ```"] # [cfg (feature = "examples")] pub fn compile_example < 'a > (target_name : & str , args : impl IntoIterator < Item = & 'a str > ,) -> crate :: assert :: Result < std :: path :: PathBuf > { crate :: debug ! ("Compiling example {}" , target_name) ; let messages = escargot :: CargoBuild :: new () . current_target () . current_release () . example (target_name) . args (args) . exec () . map_err (| e | crate :: assert :: Error :: new (e . to_string ())) ? ; for message in messages { let message = message . map_err (| e | crate :: assert :: Error :: new (e . to_string ())) ? ; let message = message . decode () . map_err (| e | crate :: assert :: Error :: new (e . to_string ())) ? ; crate :: debug ! ("Message: {:?}" , message) ; if let Some (bin) = decode_example_message (& message) { let (name , bin) = bin ? ; assert_eq ! (target_name , name) ; return bin ; } } Err (crate :: assert :: Error :: new (format ! ("Unknown error building example {target_name}"))) } # [doc = " Prepare all examples for testing"] # [doc = ""] # [doc = " Unlike `cargo_bin!`, this does not inherit all of the current compiler settings.  It"] # [doc = " will match the current target and profile but will not get feature flags.  Pass those arguments"] # [doc = " to the compiler via `args`."] # [doc = ""] # [doc = " ## Example"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " let examples = snapbox::cmd::compile_examples([]).unwrap().collect::<Vec<_>>();"] # [doc = " ```"] # [cfg (feature = "examples")] pub fn compile_examples < 'a > (args : impl IntoIterator < Item = & 'a str > ,) -> crate :: assert :: Result < impl Iterator < Item = (String , crate :: assert :: Result < std :: path :: PathBuf >) > , > { crate :: debug ! ("Compiling examples") ; let mut examples = std :: collections :: BTreeMap :: new () ; let messages = escargot :: CargoBuild :: new () . current_target () . current_release () . examples () . args (args) . exec () . map_err (| e | crate :: assert :: Error :: new (e . to_string ())) ? ; for message in messages { let message = message . map_err (| e | crate :: assert :: Error :: new (e . to_string ())) ? ; let message = message . decode () . map_err (| e | crate :: assert :: Error :: new (e . to_string ())) ? ; crate :: debug ! ("Message: {:?}" , message) ; if let Some (bin) = decode_example_message (& message) { let (name , bin) = bin ? ; examples . insert (name . to_owned () , bin) ; } } Ok (examples . into_iter ()) } # [allow (clippy :: type_complexity)] fn decode_example_message < 'm > (message : & 'm escargot :: format :: Message < '_ > ,) -> Option < crate :: assert :: Result < (& 'm str , crate :: assert :: Result < std :: path :: PathBuf >) > > { match message { escargot :: format :: Message :: CompilerMessage (msg) => { let level = msg . message . level ; if level == escargot :: format :: diagnostic :: DiagnosticLevel :: Ice || level == escargot :: format :: diagnostic :: DiagnosticLevel :: Error { let output = msg . message . rendered . as_deref () . unwrap_or_else (| | msg . message . message . as_ref ()) . to_owned () ; if is_example_target (& msg . target) { let bin = Err (crate :: assert :: Error :: new (output)) ; Some (Ok ((msg . target . name . as_ref () , bin))) } else { Some (Err (crate :: assert :: Error :: new (output))) } } else { None } } escargot :: format :: Message :: CompilerArtifact (artifact) => { if ! artifact . profile . test && is_example_target (& artifact . target) { let path = artifact . executable . clone () . expect ("cargo is new enough for this to be present") ; let bin = Ok (path . into_owned ()) ; Some (Ok ((artifact . target . name . as_ref () , bin))) } else { None } } _ => None , } } fn is_example_target (target : & escargot :: format :: Target < '_ >) -> bool { target . crate_types == ["bin"] && target . kind == ["example"] } }
    };
}

examples!()